-- ============================================================
-- 菏你同游——菏泽旅游票务平台 数据全面完善脚本
-- 执行说明：
--   1. 请先备份数据库：mysqldump -u root -p online-travel-db > backup.sql
--   2. 确保数据库编码为 utf8mb4
--   3. 在 MySQL 中执行：source update_content_full.sql
--   4. 门票价格依据2026年官方最新定价
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ============================================================
-- 第一部分：景点信息全面更新
-- 景点ID映射：
--   id=7  → 曹州牡丹园（牡丹区）
--   id=9  → 水浒好汉城（郓城县）
--   id=16 → 孙膑旅游城（鄄城县）
--   id=18 → 浮龙湖生态风景区（单县）
--   id=19 → 金山旅游区（巨野县）
--   id=20 → 老城曹州（牡丹区）
-- ============================================================

-- ==================== 1. 曹州牡丹园 (id=7) ====================
UPDATE `scenic_spot` SET
  `region_id` = 1,
  `title` = '曹州牡丹园',
  `summary` = '世界最大牡丹园，国家4A级景区，占地1600亩，拥有1200余个牡丹品种、80万株牡丹。每年4月至5月，九大色系、十大花型的牡丹竞相绽放，形成"花四海，人如潮"的壮观场面，是"中国牡丹之都"菏泽的核心赏花胜地。',
  `content` = '<p><strong>一、景点简介</strong></p><p>曹州牡丹园位于山东省菏泽市牡丹区人民路1000号，紧靠220国道，始建于1982年，是在明清以来风格不一、大小不等的十几处牡丹园基础上发展而成，如清道光年间的赵氏园、桑篱园，创于明代的毛花园等。景区占地面积1600亩，是目前世界上牡丹芍药种植面积最大、品种最多的植物园林，拥有牡丹1237个品种、芍药600余个品种，牡丹总量达80余万株，被誉为"中国牡丹之都"的核心地标。</p><p>曹州牡丹园集牡丹观赏、旅游、生产、科研于一体，园内牡丹涵盖九大色系（红、白、黄、黑、粉、紫、蓝、绿、复色）、十大花型，间植芍药、碧桃、夏莲、秋菊、腊梅、月季、玫瑰等数百种花木。每年四月中旬至五月上旬，百万株牡丹竞相开放，五彩缤纷，千姿百态，国内外游客络绎不绝，形成"花四海，人如潮"的壮观场面。2012年被评为国家4A级旅游景区，是菏泽国际牡丹文化旅游节的主会场。</p><p>牡丹在中国文化中象征着富贵吉祥，菏泽牡丹栽培历史可追溯至隋唐时期，距今已有1400余年。明清时期，曹州牡丹已达极盛，有"曹州牡丹甲天下"之美誉。如今，曹州牡丹园不仅是赏花胜地，更是牡丹文化传承与科研的重要基地，园内设有牡丹博物馆、国花馆等文化设施，深入展示牡丹的历史渊源与文化价值。</p><p><strong>二、开放时间</strong></p><p>花期（4月1日-5月20日）：08:00-21:00（20:30停止入园）</p><p>其中夜游（4月4日起）：18:30-21:00</p><p>非花期（3月9日-3月31日）：08:30-17:00</p><p>冬季灯展（2月13日-3月8日）：09:30-21:30</p><p>闭园期（5月21日-次年2月12日）：不开放</p><p>特别说明：花期开放时间可能根据花期情况微调，建议出行前关注"曹州牡丹园"官方微信公众号获取最新信息。</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市牡丹区人民路1000号（牡丹街道办事处旁）</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 赏花专线公交：每年花期开通6条赏花专线，票价2-5元。菏泽东站乘坐2308路直达曹州牡丹园东门；菏泽站乘坐2306路可达。</p><p>2. 常规公交：市内乘坐3路、16路、26路等公交车至"曹州牡丹园"站下车。</p><p>3. 牡丹节期间公交班次大幅加密，日发班次可达266班。</p><p><em>自驾路线：</em></p><p>日兰高速菏泽收费站下→沿人民路北行约5公里即达；或沿220国道至牡丹区段。</p><p><em>停车信息：</em></p><p>花期期间园区周边免费开放5300个常规车位和9326个临时车位，园区设有付费停车场。对外地游客轻微交通违法实行"首违不罚"柔性执法。</p><p><em>其他交通：</em></p><p>菏泽牡丹机场打车至园区约30-40元；菏泽东站打车约25-35元。</p><p><strong>五、特色亮点</strong></p><p>1. <em>世界之最的花海规模</em>：1600亩园区、1200余品种、80万株牡丹齐放，九大色系十大花型一站式尽览，堪称牡丹界的"大百科全书"。</p><p>2. <em>珍稀名品荟萃</em>：精品牡丹园内汇聚姚黄、魏紫、豆绿等传世名品，绿牡丹、黑牡丹等珍稀品种低调绽放，国花馆内系统展示牡丹千年文化。</p><p>3. <em>观花楼全景俯瞰</em>：登上观花楼可俯瞰千亩花海，拍摄全景大片的绝佳位置，花海与天际线交融，气势恢宏。</p><p>4. <em>梦幻夜游体验</em>：4月4日起开启夜游，300亩雾效花田配合700米激光主干道，灯光映照下的牡丹别有一番韵味，"夜赏曹州·入梦牡丹"光影秀如梦如幻。</p><p>5. <em>花神巡游与演艺</em>：花期每日定时开展十二花神巡游互动，每晚20:00上演大型水上实景演出《曹州吟·黄河纪》，融合全息投影与非遗技艺。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>4月4日至4月22日为盛花期，花海最为壮观；4月1日-3日为早花期，人少花带露、光线绝佳；4月23日至5月5日为晚花期，芍药接力绽放。</p><p><em>游览时长：</em>建议3-4小时（深度游览需5-6小时）</p><p><em>推荐路线：</em>东门入园→精品牡丹园（赏名品）→观花楼（俯瞰全景）→国花馆/牡丹博物馆（了解文化）→大田牡丹区（沉浸花海）→芍药台（晚花期必看）→夜游区（如开放）→东门出园</p><p><em>注意事项：</em></p><p>1. 实行全员预约制（含免票人员），需提前通过"曹州牡丹园"官方微信公众号预约，入园核验身份证。</p><p>2. 建议早8点前入园，人少花带露、光线柔和，拍摄效果最佳。</p><p>3. 穿浅色系服装或汉服，与牡丹花海搭配出片率极高。</p><p>4. 园区提供电瓶车服务（10元/人），步行距离较远建议乘坐。</p><p>5. 花期周末和清明节为客流高峰，建议工作日出行。</p><p>6. 园内设有多个卫生间和休息区，沿路标指示即可。</p>'
WHERE `id` = 7;

-- ==================== 2. 水浒好汉城 (id=9) ====================
UPDATE `scenic_spot` SET
  `region_id` = 7,
  `title` = '水浒好汉城',
  `summary` = '国家4A级景区，占地400余亩，拥有36院落、72景观、108个景点。以水浒文化为主题，集古建筑群、武术表演、情景剧演绎于一体，让游客一秒穿越北宋，体验梁山好汉的豪情壮志。郓城是《水浒传》故事发源地，好汉之乡名不虚传。',
  `content` = '<p><strong>一、景点简介</strong></p><p>水浒好汉城位于山东省菏泽市郓城县水浒路西段，是国家4A级旅游景区，也是全国唯一一处以水浒文化为主题、集古建筑群与武术文化于一体的综合性景区。景区占地400余亩，拥有36院落、72景观、108个景点，完美再现了《水浒传》中梁山好汉的传奇世界。</p><p>郓城始建于鲁成公四年（公元前587年），是名副其实的千年古县，自建城以来便与武术、军事有着密切联系。这里是《水浒传》故事的发源地，托塔天王晁盖、及时雨宋江皆为郓城人氏。郓城是中国好汉之乡、全国武术之乡、书画之乡、戏曲之乡、古筝之乡，文化底蕴极为深厚。</p><p>景区分为三大功能区：一是水浒古城核心游览区，汇聚了水浒文化博物馆、郓城县衙、晁家庄、宋江武馆、及时雨茶楼、孙二娘客栈等传统北方四合院和浙派、徽派古代建筑群，可欣赏非物质文化遗产项目及古装情景剧表演；二是武术修学区，狗娃艺术团的精彩表演和重达200余斤的状元大刀绝技令人震撼；三是购物休闲区，提供特色美食与文创产品。</p><p>水浒好汉城将水浒旅游与中国武术完美结合，开展武术比赛、武术表演、武术修学旅游等活动，以武促旅，让游客在游览中感受忠义精神与好汉豪情。正如古语所言："读水浒掩卷长叹，遥想一百单八将，叹彼时若无郓城，哪得英雄聚水泊。"</p><p><strong>二、开放时间</strong></p><p>夏季（5月-10月）：7:30-18:30</p><p>春、秋、冬季（11月-次年4月）：8:00-18:00</p><p>节假日夜间可能延长至21:00-21:30</p><p>游览时长建议：1.5-2.5小时</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市郓城县水浒路西段（西门街南段）</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 菏泽市区乘坐郓城方向城际公交至郓城汽车站，换乘县内公交或出租车约10分钟可达。</p><p>2. 郓城县城内乘坐出租车约5-10分钟可达景区。</p><p><em>自驾路线：</em></p><p>日兰高速郓城收费站下→沿S339省道东行→转入水浒路即达；或沿G220国道至郓城段。</p><p><em>停车信息：</em></p><p>景区设有收费停车场，车位充足。</p><p><em>其他交通：</em></p><p>菏泽东站至景区约40分钟车程；菏泽站至景区约30分钟车程。</p><p><strong>五、特色亮点</strong></p><p>1. <em>忠义楼——景区地标</em>：明清风格纯木结构楼阁，一层为水浒文化博物馆，登高可远眺景区全景，是水浒好汉城的精神象征。</p><p>2. <em>实景情景剧——沉浸式体验</em>：《李逵坐衙》黑色幽默风格令人捧腹，《武松醉打蒋门神》拳拳到肉，《智取生辰纲》实景演绎智谋对决，每日多场演出精彩不断。</p><p>3. <em>晁家庄迷宫——暗道探险</em>：托塔天王晁盖的庄院，内设3D水浒画展和地宫迷宫，可体验暗道逃生，刺激好玩。</p><p>4. <em>宋江武馆——武术盛宴</em>：狗娃艺术团的精彩武术表演、200余斤状元大刀绝技展示，热血沸腾，感受中华武术的博大精深。</p><p>5. <em>好汉迎宾仪式</em>：每日9:00举行开城仪式，古装武士列队迎宾，一秒穿越回北宋江湖。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>春秋两季最为舒适；下午3点后入园光影出片效果最佳；节假日可体验夜场。</p><p><em>游览时长：</em>建议2-3小时</p><p><em>推荐路线：</em>景区大门（看好汉迎宾仪式）→忠义楼（水浒博物馆）→郓城县衙（看《李逵坐衙》）→晁家庄（闯迷宫）→宋江武馆（看武术表演）→古筝坊（非遗体验）→孙二娘客栈→及时雨茶楼→水浒书场→出园</p><p><em>注意事项：</em></p><p>1. 景区提供古装/侠客服租赁服务，穿上拍照江湖感满满。</p><p>2. 情景剧演出时间固定，建议入园后先查看当日演出时刻表。</p><p>3. 晁家庄迷宫较暗，注意脚下安全。</p><p>4. 景区内有孙二娘包子铺等特色餐饮，可品尝武大郎炊饼、郓城壮馍等水浒主题美食。</p><p>5. 咨询电话：0530-6896888</p>'
WHERE `id` = 9;

-- ==================== 3. 孙膑旅游城 (id=16) ====================
UPDATE `scenic_spot` SET
  `region_id` = 8,
  `title` = '孙膑旅游城',
  `summary` = '国家4A级景区，战国军事家孙膑故里，占地999亩。景区由孙膑纪念区、佛教文化区、园林游览区三大区域组成，拥有亿城寺、孙膑墓、羊左合葬墓、荆轲墓等历史遗迹，是国家首批十二条精品旅游线路之一。',
  `content` = '<p><strong>一、景点简介</strong></p><p>孙膑旅游城坐落在山东省菏泽市鄄城县东北20公里处的箕山镇境内，占地面积999亩，是国家4A级旅游景区，已被纳入国家首批十二条精品旅游线路之一，并被评为山东省最具特色影视拍摄基地。鄄城乃战国著名军事家孙膑的故里，《孙膑兵法》是举世公认的兵学圣典，孙膑旅游城正是在中国古"亿城寺"遗址的基础上兴建而成。</p><p>整个景区划分为三大区域：孙膑纪念区、佛教文化区和园林游览区。孙膑纪念区以孙膑纪念馆为核心，包含武圣门、孙膑纪念堂、孙膑墓、九宫八卦迷魂阵、兵法文化长廊等景点，全面展示孙膑的军事思想与传奇人生。佛教文化区以亿城寺为主体，亿城寺始建于北魏时期，距今已有1500余年历史，寺内有大雄宝殿、天王殿、放生池等佛教建筑，香火鼎盛。园林游览区栽植各种花草树木，品种繁多，圆融湖碧波粼粼，亭台点缀其间，春日繁花似锦，夏日清凉宜人。</p><p>孙膑，战国时期齐国军师，与庞涓同师鬼谷子，因遭庞涓嫉妒被施膑刑（挖去膝盖骨），后逃至齐国，辅佐田忌赛马取胜，并在马陵之战中大败魏军，逼死庞涓，留下"围魏救赵""减灶诱敌"等经典战例。孙膑旅游城让游客在游览中感受兵家智慧与忠义文化，是一处集历史文化、佛教文化、园林景观于一体的综合性旅游景区。</p><p><strong>二、开放时间</strong></p><p>春冬季（11月-次年4月）：8:30-17:30</p><p>夏秋季（5月-10月）：8:30-18:00</p><p>全年开放，无闭馆日</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市鄄城县箕山镇孙花园村北</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 菏泽市区乘坐鄄城方向城际公交至鄄城汽车站，换乘至箕山镇的班车。</p><p>2. 鄄城县城乘坐出租车约20分钟可达景区。</p><p><em>自驾路线：</em></p><p>日兰高速鄄城收费站下→沿S338省道东北方向行驶约20公里至箕山镇即达。</p><p><em>停车信息：</em></p><p>景区设有免费停车场，停车便利。</p><p><em>其他交通：</em></p><p>菏泽东站自驾约1小时可达。</p><p><strong>五、特色亮点</strong></p><p>1. <em>九宫八卦迷魂阵——互动体验</em>：相传由伏羲创建，孙膑首次将其运用于军事。进入阵中，方向随时在变，南北中有东西，东西中有南北，令人迷方向，趣味十足。当地有顺口溜："进了迷魂阵，状元也难认，东西南北中，到处是胡同。"</p><p>2. <em>亿城寺——千年古刹</em>：始建于北魏，距今1500余年，寺内大雄宝殿气势恢宏，香火鼎盛，是鲁西南地区重要的佛教文化圣地。</p><p>3. <em>孙膑纪念馆——兵圣致敬</em>：重檐串尖屋顶式建筑，长宽各30米，高20米，飞檐半拱青琉璃瓦顶，内设孙膑生平展、兵法文化长廊，系统展示孙膑的军事思想。</p><p>4. <em>羊左合葬墓——忠义典范</em>：羊角哀与左伯桃的合葬墓，二人"舍命全交"的故事是中华忠义文化的经典象征，感人至深。</p><p>5. <em>圆融湖——自然风光</em>：碧波粼粼的湖面与亭台楼阁相映成趣，林荫道绿意葱茏，是休闲漫步、亲近自然的绝佳去处。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>春季（4-5月）和秋季（9-10月）气候宜人；建议错峰游览更惬意。</p><p><em>游览时长：</em>建议3-4小时</p><p><em>推荐路线：</em>城门（观甲骨文浮雕）→圆融广场→兵圣门→九宫八卦迷魂阵→孙膑纪念馆→孙膑墓→亿城寺→羊左合葬墓→圆融湖→出园</p><p><em>注意事项：</em></p><p>1. 迷魂阵内方向感易失，建议跟随指示牌或导游行进。</p><p>2. 亿城寺为宗教场所，请保持安静，尊重宗教习俗。</p><p>3. 景区面积较大，建议穿舒适平底鞋。</p><p>4. 适合研学旅行、亲子游、古风打卡。</p><p>5. 咨询电话：0530-2885666</p>'
WHERE `id` = 16;

-- ==================== 4. 浮龙湖生态风景区 (id=18) ====================
UPDATE `scenic_spot` SET
  `region_id` = 4,
  `title` = '浮龙湖生态风景区',
  `summary` = '被誉为"故道明珠、江北西湖"，水域面积是杭州西湖的4倍。黄河故道上的生态明珠，集湖泊观光、湿地生态、水上娱乐、休闲度假于一体，是鲁西南地区最大的平原水库风景区。',
  `content` = '<p><strong>一、景点简介</strong></p><p>浮龙湖生态风景区位于山东省菏泽市单县西南部，地处黄河故道之上，是鲁西南地区最大的平原水库风景区，被誉为"故道明珠、江北西湖"。浮龙湖水域面积达25平方公里，是杭州西湖水域面积的4倍，湖面烟波浩渺，碧波万顷，湖中岛屿星罗棋布，湖岸线蜿蜒曲折，自然风光秀美壮观。</p><p>浮龙湖的形成与黄河改道密切相关。历史上黄河多次改道南流，在单县境内留下了宽阔的黄河故道，后经蓄水形成了如今的浮龙湖。湖区生态环境优越，水草丰茂，鱼类资源丰富，是多种候鸟的栖息地，秋冬时节成群结队的候鸟在此停歇，构成一幅动人的自然画卷。</p><p>景区以生态保护为前提，开发了水上观光、湿地科普、休闲垂钓、生态采摘等旅游项目。湖畔建有环湖绿道、观景平台、亲水栈道等设施，游客可乘船游湖、骑行环湖、漫步栈道，全方位感受浮龙湖的自然之美。景区内的月亮湾湿地是观鸟爱好者的天堂，木栈道穿行于芦苇荡中，步步皆景。</p><p>浮龙湖不仅自然风光优美，还承载着深厚的黄河文化。景区内设有黄河故道文化展示区，通过实物、图片、文字等形式，讲述黄河改道的历史变迁和沿岸人民与黄河共生共荣的故事，是一处集自然观光、生态教育、文化体验于一体的综合性旅游景区。</p><p><strong>二、开放时间</strong></p><p>全年开放，全天24小时（水上项目运营时间：8:00-17:30）</p><p>夏季（5月-10月）水上项目延长至18:00</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市单县浮岗镇浮龙湖生态风景区</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 单县县城乘坐浮龙湖方向公交班车，约30分钟可达。</p><p>2. 菏泽市区乘坐单县方向城际公交至单县汽车站，换乘浮龙湖方向班车。</p><p><em>自驾路线：</em></p><p>德上高速单县收费站下→沿S349省道西南方向行驶约15公里即达；或沿G105国道至单县段转S349。</p><p><em>停车信息：</em></p><p>景区设有大型免费停车场。</p><p><em>其他交通：</em></p><p>菏泽东站自驾约1小时可达；单县县城打车约30元。</p><p><strong>五、特色亮点</strong></p><p>1. <em>浩渺湖景——江北西湖</em>：25平方公里的广阔水域，烟波浩渺，碧波万顷，日落时分黄河故道上空的晚霞倒映湖面，拍照绝美。</p><p>2. <em>月亮湾湿地——生态秘境</em>：木栈道穿行于芦苇荡中，候鸟翩跹，是观鸟、摄影、亲近自然的绝佳去处。</p><p>3. <em>水上娱乐——湖上畅游</em>：提供游船、画舫、皮划艇等多种水上项目，泛舟湖上，清风拂面，尽享水上乐趣。</p><p>4. <em>环湖绿道——骑行天堂</em>：全长约20公里的环湖绿道，沿途风景如画，是骑行和徒步爱好者的理想选择。</p><p>5. <em>黄河故道文化——历史记忆</em>：黄河故道文化展示区讲述黄河改道的历史变迁，感受人与自然共生共荣的智慧。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>春夏秋三季皆宜，4-10月为最佳；秋冬候鸟迁徙季节可观鸟。</p><p><em>游览时长：</em>建议3-5小时（环湖骑行需4-5小时）</p><p><em>推荐路线：</em>景区入口→游客中心→月亮湾湿地（观鸟栈道）→游船码头（乘船游湖）→生态岛→环湖绿道（骑行/徒步）→黄河故道文化展示区→出园</p><p><em>注意事项：</em></p><p>1. 湖区紫外线较强，注意防晒。</p><p>2. 水上项目请穿好救生衣，注意安全。</p><p>3. 湿地区域请勿惊扰鸟类，保持安静。</p><p>4. 环湖骑行全程约20公里，请根据体力合理安排。</p><p>5. 湖畔农家乐可品尝黄河鲤鱼、单县羊肉汤等当地美食。</p>'
WHERE `id` = 18;

-- ==================== 5. 金山旅游区 (id=19) ====================
UPDATE `scenic_spot` SET
  `region_id` = 6,
  `title` = '金山旅游区',
  `summary` = '菏泽唯一山景胜地，泰山余脉，国家3A级景区。以秦王避暑洞（汉代崖墓）、金山寺、中华道观为核心景点，南佛北道共处一山，登山祈福、探古寻幽，人文与自然双丰收。',
  `content` = '<p><strong>一、景点简介</strong></p><p>金山旅游区位于山东省菏泽市巨野县城东南23公里处，属泰山余脉，是菏泽市唯一的山岳型景区，素有"菏泽第一山"之称。金山海拔虽不及名山大川，但在一望无际的鲁西南平原上拔地而起，显得格外雄伟壮观，自古便有"登金山而小鲁西"之说。</p><p>金山历史悠久，文化底蕴深厚。相传秦始皇东巡时曾在此避暑，留下了著名的"秦王避暑洞"——一处开凿于山体之中的汉代崖墓，洞内恒温18℃，冬暖夏凉，洞壁上刻有精美的摩崖石刻，是研究汉代丧葬文化的重要实物资料。金山还是南佛北道共处一山的宗教圣地，山上有金山寺和中华道观，佛道和谐共存，香火鼎盛，登山祈福者络绎不绝。</p><p>景区自然风光秀美，山体虽不高但植被茂密，四季景色各异：春季山花烂漫，夏季绿树成荫，秋季红叶满山，冬季银装素裹。山间清泉潺潺，古树参天，登临山顶可远眺鲁西南平原的壮阔景色。此外，金山还曾是刘邓大军千里跃进大别山时的临时指挥所所在地，红色文化资源丰富。</p><p>金山旅游区集山岳观光、宗教朝拜、历史探秘、红色教育于一体，是菏泽市民周末休闲的首选之地，也是外地游客了解菏泽山水文化的窗口。</p><p><strong>二、开放时间</strong></p><p>全年开放：8:00-17:00</p><p>夏季（5月-10月）可能延长至17:30</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市巨野县核桃园镇金山旅游区</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 巨野县城乘坐金山方向公交班车，约40分钟可达。</p><p>2. 菏泽市区乘坐巨野方向城际公交至巨野汽车站，换乘金山方向班车。</p><p><em>自驾路线：</em></p><p>日兰高速巨野收费站下→沿S254省道东南方向行驶约20公里至核桃园镇即达。</p><p><em>停车信息：</em></p><p>景区山脚设有免费停车场。</p><p><em>其他交通：</em></p><p>菏泽东站自驾约50分钟可达。</p><p><strong>五、特色亮点</strong></p><p>1. <em>秦王避暑洞——千年崖墓</em>：开凿于山体之中的汉代崖墓，洞内恒温18℃，冬暖夏凉，洞壁摩崖石刻精美绝伦，是研究汉代丧葬文化的珍贵实物。</p><p>2. <em>南佛北道——宗教圣地</em>：金山寺与中华道观共处一山，佛道和谐共存，在北方地区极为罕见，登山祈福、感受宗教文化的包容与多元。</p><p>3. <em>平原独峰——菏泽第一山</em>：在一望无际的鲁西南平原上拔地而起，登临山顶可远眺平原壮阔景色，"登金山而小鲁西"。</p><p>4. <em>红色记忆——刘邓大军指挥所</em>：刘邓大军千里跃进大别山时的临时指挥所旧址，是红色教育的重要场所。</p><p>5. <em>四季风光——自然画卷</em>：春花烂漫、夏荫清凉、秋叶如火、冬雪银装，四季皆有不同风景。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>春秋两季最为舒适；夏季可入秦王避暑洞纳凉。</p><p><em>游览时长：</em>建议2-3小时</p><p><em>推荐路线：</em>景区入口→金山寺→秦王避暑洞→中华道观→山顶观景台→刘邓大军指挥所旧址→下山出园</p><p><em>注意事项：</em></p><p>1. 山路较陡，建议穿防滑运动鞋。</p><p>2. 秦王避暑洞内较暗，注意脚下安全。</p><p>3. 宗教场所请保持安静，尊重宗教习俗。</p><p>4. 山顶风大，注意保暖。</p>'
WHERE `id` = 19;

-- ==================== 6. 老城曹州 (id=20) ====================
UPDATE `scenic_spot` SET
  `region_id` = 1,
  `title` = '老城曹州',
  `summary` = '菏泽网红打卡新地标，仿古建筑群与璀璨夜灯交相辉映，是古风摄影的天堂。永安塔、慎思园、1446街等核心景点，白天青砖黛瓦，夜晚灯火辉煌，水幕光影秀与打铁花表演令人叹为观止。免费开放，汉服友好景区。',
  `content` = '<p><strong>一、景点简介</strong></p><p>老城曹州位于山东省菏泽市牡丹区水洼北街青年湖公园北侧，是菏泽近年来倾力打造的文化旅游新地标。景区深入挖掘曹州传统文化特色，以仿古建筑群为核心，融合特色美食、传统手工作坊、艺术表演等业态与现代休闲娱乐业态，打造了一座集吃、住、行、游、购、娱于一体的一站式文旅商业综合体。</p><p>老城曹州以明清建筑风格为基调，青砖黛瓦、飞檐翘角、石板街巷，完美再现了古曹州的城市风貌。景区核心景点包括56米高的七层八角永安塔、精巧雅致的慎思园、充满烟火气的1446街、古城墙遗址等。白天漫步青石板路，感受古韵悠然；夜晚华灯初上，整座古城流光溢彩，仿佛穿越回千年前的繁华曹州。</p><p>菏泽古称曹州，是伏羲桑梓、尧舜故里，历史悠久、文化灿烂。菏泽还是全国40%汉服的产地，老城曹州充分利用这一优势，打造了"汉服友好"景区，城内设有唐、宋、明等朝代风格的免费打卡点，游客可租赁汉服在古建筑前拍照，氛围感十足。</p><p>老城曹州最令人期待的当属夜间演艺。青年湖水幕光影秀配合音乐喷泉，水与光交织出梦幻画卷；漫天铁花与水上飞人交织的奇景，将千年非遗技艺与现代科技完美融合，令人叹为观止。景区免费开放，是菏泽市民和游客夜游的首选之地。</p><p><strong>二、开放时间</strong></p><p>全天24小时开放，全年无休</p><p>夜间演艺时间：通常为19:30-21:00（具体以景区公告为准）</p><p>永安塔开放时间：9:00-21:00</p><p><strong>三、详细地址</strong></p><p>山东省菏泽市牡丹区水洼北街青年湖公园北侧约120米</p><p><strong>四、交通方式</strong></p><p><em>公共交通：</em></p><p>1. 市内乘坐2路、5路、13路等公交车至"老城曹州"或"青年湖"站下车步行即达。</p><p>2. 距菏泽火车站约3公里，打车约10元。</p><p><em>自驾路线：</em></p><p>日兰高速菏泽收费站下→沿人民路至牡丹区→转入水洼北街即达。</p><p><em>停车信息：</em></p><p>景区设有免费停车场。</p><p><em>其他交通：</em></p><p>菏泽东站打车约25元；菏泽站打车约10元。</p><p><strong>五、特色亮点</strong></p><p>1. <em>永安塔——古城地标</em>：56米高的七层八角塔，登塔可俯瞰老城全貌和青年湖美景，蓝天作背景仰拍秒出大片。</p><p>2. <em>水幕光影秀——夜游高光</em>：青年湖上水幕光影秀配合音乐喷泉，水与光交织出梦幻画卷，是老城曹州最震撼的夜间表演。</p><p>3. <em>打铁花——非遗奇观</em>：漫天铁花与水上飞人交织，千年非遗技艺在夜空中绽放，火树银花不夜天。</p><p>4. <em>1446街——烟火人间</em>：青石板路配灯笼暖光，特色小吃、手工艺品、文创店铺林立，傍晚时分走拍超灵动。</p><p>5. <em>汉服友好——国风出片</em>：菏泽是全国40%汉服产地，城内设有多个朝代风格打卡点，租赁汉服拍照氛围感拉满。</p><p><strong>六、游览建议</strong></p><p><em>最佳游览时间：</em>傍晚至夜间最佳，先拍白天青砖黛瓦，再等夜灯亮起，一园两景；周末和节假日夜间演艺更丰富。</p><p><em>游览时长：</em>建议2-3小时（含夜间演艺）</p><p><em>推荐路线：</em>景区入口→1446街（逛吃打卡）→慎思园（亭台回廊）→古城墙遗址→永安塔（登塔远眺）→青年湖畔（等夜幕降临）→水幕光影秀→打铁花表演→出园</p><p><em>注意事项：</em></p><p>1. 景区免费开放，永安塔登塔需另购门票20元。</p><p>2. 夜间演艺时间可能调整，建议提前关注"老城曹州"官方公众号。</p><p>3. 建议穿汉服或浅色服装游览，与古建筑搭配出片率极高。</p><p>4. 1446街美食众多，推荐品尝单县羊肉汤、曹州烧饼、水煎包等菏泽特色小吃。</p><p>5. 咨询电话：0530-7911111</p>'
WHERE `id` = 20;

